WITH enriched AS (SELECT id, channel, promo_code, starts_on, ends_on, discount_pct, DENSE_RANK() OVER (PARTITION BY channel ORDER BY discount_pct DESC) discount_pct_dense_rank, FIRST_VALUE(channel) IGNORE NULLS OVER (ORDER BY discount_pct, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) first_known_channel, AVG(discount_pct) OVER w_part discount_pct_avg_5_prior, PERCENT_RANK() OVER w_ordered discount_pct_percent_rank FROM promotions WINDOW w_part AS (PARTITION BY channel ORDER BY starts_on, id ROWS BETWEEN 5 PRECEDING AND 1 PRECEDING), w_ordered AS (PARTITION BY promo_code ORDER BY discount_pct)), matched AS (SELECT src.*, pr.id AS promo_id, pr.promo_code AS promotion_promo_code, pr.discount_pct AS promotion_discount_pct FROM enriched src LEFT JOIN promotions pr ON src.channel = pr.channel AND src.ends_on BETWEEN pr.starts_on AND pr.ends_on), matched_promotions AS (SELECT s.*, pr.id AS promo_id_2, pr.promo_code AS promotion_promo_code_2, pr.discount_pct AS promotion_discount_pct_2 FROM matched s LEFT JOIN promotions pr ON s.channel <=> pr.channel AND s.ends_on >= pr.starts_on AND s.ends_on < pr.ends_on + INTERVAL '7' DAY), matched_promotions_2 AS (SELECT e.*, pr.id AS promo_id_3, pr.promo_code AS promotion_promo_code_3, pr.discount_pct AS promotion_discount_pct_3 FROM matched_promotions e LEFT JOIN promotions pr ON e.channel = pr.channel AND e.ends_on BETWEEN pr.starts_on AND pr.ends_on), with_window AS (SELECT s.*, pr.id AS promo_id_4, pr.promo_code AS promotion_promo_code_4, pr.discount_pct AS promotion_discount_pct_4 FROM matched_promotions_2 s INNER JOIN promotions pr ON s.channel = pr.channel AND s.starts_on >= pr.starts_on AND s.starts_on < pr.ends_on + INTERVAL 7 DAYS), scored AS (SELECT *, SUM(promotion_discount_pct_2) OVER (PARTITION BY promo_code, promotion_promo_code_4 ORDER BY discount_pct, id, promo_id, promo_id_2, promo_id_3, promo_id_4 ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) cumulative_promotion_discount_pct_2, ROW_NUMBER() OVER (PARTITION BY promotion_promo_code_4 ORDER BY ends_on, id, promo_id, promo_id_2, promo_id_3, promo_id_4) event_seq, RANK() OVER (PARTITION BY promotion_promo_code_4 ORDER BY promotion_discount_pct_2 DESC) promotion_discount_pct_2_rank FROM with_window) SELECT promotion_promo_code_3, COUNT(DISTINCT promotion_promo_code_4) AS distinct_promotion_promo_code_4s, SIZE(COLLECT_SET(promotion_promo_code)) AS num_promotion_promo_codes FROM scored GROUP BY promotion_promo_code_3 HAVING num_promotion_promo_codes >= 1 ORDER BY promotion_promo_code_3 DESC
